const VERSION='dc-guide-v5-update-refresh';
const SHELL=VERSION+'-shell',PHOTOS='dc-guide-photos';
const ASSETS=['./','index.html','styles.css?v=20261106-5','app.js?v=20261106-5','core.js?v=20261106-5','study.js?v=20261106-5','study.css?v=20261106-5','catalog.json','manifest.webmanifest','icon.svg','icon-192.png','icon-512.png','assets-manifest.json'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(SHELL).then(async cache=>{const files=await fetch('assets-manifest.json',{cache:'no-store'}).then(r=>r.json());await cache.addAll([...ASSETS,...files].map(path=>new Request(new URL(path,self.registration.scope),{cache:'reload'})));}));self.skipWaiting();});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{const photos=await caches.open(PHOTOS);for(const key of await caches.keys()){if(key.startsWith('dc-guide-')&&key.endsWith('-photos')&&key!==PHOTOS){const old=await caches.open(key);for(const request of await old.keys())if(!await photos.match(request)){const response=await old.match(request);if(response)await photos.put(request,response);}}if(key.startsWith('dc-guide-')&&key!==SHELL&&key!==PHOTOS)await caches.delete(key);}await self.clients.claim();})());});
const localImage=url=>url.origin===self.location.origin&&/^\/assets\/products\/[a-z0-9-]+\.webp$/.test(url.pathname);
const officialImage=url=>url.protocol==='https:'&&(['dalcotone.com.br','www.dalcotone.com.br','cdn.shopify.com'].includes(url.hostname))&&(/\/cdn\/shop\//.test(url.pathname)||url.hostname==='cdn.shopify.com');
self.addEventListener('fetch',event=>{const request=event.request;if(request.method!=='GET')return;const url=new URL(request.url);if(url.origin===self.location.origin){if(request.mode==='navigate'&&[new URL('./',self.registration.scope).pathname,new URL('index.html',self.registration.scope).pathname].includes(url.pathname)){event.respondWith(fetch(request).then(async response=>{if(response.ok){const cache=await caches.open(SHELL);await cache.put('index.html',response.clone());}return response;}).catch(()=>caches.match('index.html')));return;}if(url.pathname.endsWith('/catalog.json')){event.respondWith(fetch(request).then(async response=>{if(response.ok){const cache=await caches.open(SHELL);await cache.put('catalog.json',response.clone());}return response;}).catch(()=>caches.match('catalog.json')));return;}if(localImage(url)||ASSETS.some(a=>new URL(a,self.registration.scope).pathname===url.pathname)){event.respondWith(caches.match(request).then(cached=>cached||fetch(request)));}return;}if(officialImage(url)){event.respondWith(caches.open(PHOTOS).then(async cache=>{const cached=await cache.match(request);if(cached)return cached;const response=await fetch(request);if(response.ok||response.type==='opaque')await cache.put(request,response.clone());return response;}));}});
self.addEventListener('message',event=>{const port=event.ports[0];if(!port)return;const images=[...new Set(Array.isArray(event.data?.images)?event.data.images:[])].map(value=>{try{return new URL(value,self.registration.scope).href;}catch{return '';}}).filter(value=>value&&(localImage(new URL(value))||officialImage(new URL(value)))).slice(0,300);if(event.data.type==='STATUS'){event.waitUntil((async()=>{const shell=await caches.open(SHELL),photos=await caches.open(PHOTOS);const ready=await Promise.all(ASSETS.map(a=>shell.match(a)));const matches=await Promise.all(images.map(url=>localImage(new URL(url))?shell.match(url):photos.match(url)));port.postMessage({shellReady:ready.every(Boolean),imagesCached:matches.filter(Boolean).length});})());}if(event.data.type==='DOWNLOAD'){event.waitUntil((async()=>{try{const shell=await caches.open(SHELL);const files=await fetch('assets-manifest.json',{cache:'no-store'}).then(r=>r.json());await shell.addAll([...ASSETS,...files].map(path=>new Request(new URL(path,self.registration.scope),{cache:'reload'})));const cache=await caches.open(PHOTOS);let done=0,saved=0;const pending=images.slice();async function download(){while(pending.length){const url=pending.shift();const target=localImage(new URL(url))?shell:cache;try{let response=await target.match(url);if(!response){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),15000);try{response=await fetch(url,{mode:localImage(new URL(url))?'same-origin':'no-cors',credentials:localImage(new URL(url))?'same-origin':'omit',signal:controller.signal});}finally{clearTimeout(timer);}if(response.ok||response.type==='opaque')await target.put(url,response.clone());else throw Error('Image unavailable');}saved++;}catch{}done++;port.postMessage({type:'PROGRESS',done,total:images.length,saved,message:`Fotos armazenadas: ${saved} de ${images.length}.`});}}await Promise.all(Array.from({length:4},download));port.postMessage({type:'DONE',done,total:images.length,saved,message:`Catálogo salvo. Fotos armazenadas: ${saved} de ${images.length}.${saved<images.length?' Algumas fotos não baixaram; tente novamente com internet.':''}`});}catch{port.postMessage({type:'ERROR',message:'Não foi possível completar o armazenamento offline. Confira a conexão e o espaço disponível.'});}})());}});
